import{_ as r,a0 as s,w as p,s as d,ao as l,I as i,x as t,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何使用 Wine 在 Linux 下玩魔獸世界 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Wine 在 Linux 下玩魔獸世界 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Wine 在 Linux 下玩魔獸世界 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Wine 在 Linux 下玩魔獸世界 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20170928 How to Play World of Warcraft On Linux With Wine","title":"如何使用 Wine 在 Linux 下玩魔獸世界","tag":"201712","desc":""},"relativePath":"201712/20170928 How to Play World of Warcraft On Linux With Wine.md","filePath":"[post].md"}'),g={name:"201712/20170928 How to Play World of Warcraft On Linux With Wine.md"};function u(W,n,f,x,w,m){const e=s("Link");return p(),d("div",null,[n[25]||(n[25]=l('<h1 id="如何使用-wine-在-linux-下玩魔獸世界" tabindex="-1">如何使用 Wine 在 Linux 下玩魔獸世界 <a class="header-anchor" href="#如何使用-wine-在-linux-下玩魔獸世界" aria-label="Permalink to “如何使用 Wine 在 Linux 下玩魔獸世界”">​</a></h1><p><strong>目標：</strong>在 Linux 中運行魔獸世界</p><p><strong>發行版：</strong>適用於幾乎所有的 Linux 發行版。</p><p><strong>要求：</strong>具有 root 權限的 Linux 系統，搭配上比較現代化的顯卡並安裝了最新的圖形驅動程序。</p><p><strong>難度：</strong>簡單</p><p><strong>約定：</strong></p><ul><li><code>#</code> - 要求以 root 權限執行命令，可以直接用 root 用户來執行也可以使用 <code>sudo</code> 命令</li><li><code>$</code> - 使用普通非特權用户執行</li></ul><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p>魔獸世界已經出現差不多有 13 年了，但它依然是最流行的 MMORPG。 不幸的是， 一直以來暴雪從未發佈過官方的 Linux 客户端。 不過還好，我們有 Wine。</p><h3 id="安裝-wine" tabindex="-1">安裝 Wine <a class="header-anchor" href="#安裝-wine" aria-label="Permalink to “安裝 Wine”">​</a></h3><p>你可以試着用一下普通的 Wine，但它在遊戲性能方面改進不大。 Wine Staging 以及帶 Gallium Nine 補丁的 Wine 幾乎在各方面都要更好一點。 如果你使用了閉源的驅動程序， 那麼 Wine Staging 是最好的選擇。 若使用了 Mesa 驅動程序， 則還需要打上 Gallium Nine 補丁。</p>',11)),i("p",null,[n[1]||(n[1]=t("根據你使用的發行版，參考 ",-1)),o(e,{href:"https://linuxconfig.org/installing-wine"},{default:a(()=>[...n[0]||(n[0]=[t("Wine 安裝指南",-1)])]),_:1}),n[2]||(n[2]=t(" 來安裝。",-1))]),n[26]||(n[26]=l('<h3 id="winecfg" tabindex="-1">Winecfg <a class="header-anchor" href="#winecfg" aria-label="Permalink to “Winecfg”">​</a></h3><p>打開 <code>winecfg</code>。確保第一個標籤頁中的 Windows 版本已經設置成了 <code>Windows 7</code>。 暴雪不再對之前的版本提供支持。 然後進入 “Staging” 標籤頁。 這裏根據你用的是 staging 版本的 Wine 還是打了 Gallium 補丁的 Wine 來進行選擇。</p><p><img src="https://linuxconfig.org/images/wow-wine-staging.jpg" alt="Winecfg Staging Settings"></p><p>不管是哪個版本的 Wine，都需要啓用 VAAPI 以及 EAX。 至於是否隱藏 Wine 的版本則由你自己決定。</p><p>如果你用的是 Staging 補丁，則啓用 CSMT。 如果你用的是 Gallium Nine，則啓用 Gallium Nine。 但是你不能兩個同時啓用。</p><h3 id="winetricks" tabindex="-1">Winetricks <a class="header-anchor" href="#winetricks" aria-label="Permalink to “Winetricks”">​</a></h3>',6)),i("p",null,[n[4]||(n[4]=t("下一步輪到 Winetricks 了。如果你對它不瞭解，那我告訴你， Winetricks 一個用來為 Wine 安裝各種 Windows 庫以及組件以便程序正常運行的腳本。 更多信息可以閲讀我們的這篇文章 ",-1)),o(e,{href:"https://linuxconfig.org/configuring-wine-with-winetricks"},{default:a(()=>[...n[3]||(n[3]=[t("Winetricks 指南",-1)])]),_:1}),n[5]||(n[5]=t("：",-1))]),n[27]||(n[27]=i("p",null,[i("img",{src:"https://linuxconfig.org/images/wow-wine-corefonts.jpg",alt:"Winetricks Corefonts Installed"})],-1)),n[28]||(n[28]=i("p",null,[t("要讓 WoW 以及"),i("ruby",null,[t("戰網啓動程序"),i("rt",null,"Battle.net launcher")]),t("工作需要安裝一些東西。首先，在 “Fonts” 部分中安裝 "),i("code",null,"corefonts"),t("。 然後下面這一步是可選的， 如果你希望來自互聯網上的所有數據都顯示在戰網啓動程序中的話，就還需要安裝 DLL 部分中的 ie8。")],-1)),n[29]||(n[29]=i("h3",{id:"battle-net",tabindex:"-1"},[t("Battle.net "),i("a",{class:"header-anchor",href:"#battle-net","aria-label":"Permalink to “Battle.net”"},"​")],-1)),i("p",null,[n[7]||(n[7]=t("現在你配置好了 Wine 了，可以安裝 Battle.net 應用了。 Battle.net 應用用來安裝和升級 WoW 以及其他暴雪遊戲。 它經常在升級後會出現問題。 因此若它突然出現問題，請查看 ",-1)),o(e,{href:"https://appdb.winehq.org/objectManager.php?sClass=version&iId=28855&iTestingId=98594"},{default:a(()=>[...n[6]||(n[6]=[t("WineHQ 頁面",-1)])]),_:1}),n[8]||(n[8]=t("。",-1))]),i("p",null,[n[10]||(n[10]=t("毫無疑問，你可以從 ",-1)),o(e,{href:"http://us.battle.net/en/app/"},{default:a(()=>[...n[9]||(n[9]=[t("Blizzard 的官網上",-1)])]),_:1}),n[11]||(n[11]=t(" 下載 Battle.net 應用。",-1))]),n[30]||(n[30]=l('<p>下載完畢後，使用 Wine 打開 <code>.exe</code> 文件， 然後按照安裝指引一步步走下去，就跟在 Windows 上一樣。</p><p><img src="https://linuxconfig.org/images/wow-bnet.jpg" alt="Battle.net Launcher With WoW Installed"></p><p>應用安裝完成後，登錄/新建帳號就會進入啓動器界面。 你在那可以安裝和管理遊戲。 然後開始安裝 WoW。 這可得好一會兒。</p><h3 id="運行遊戲" tabindex="-1">運行遊戲 <a class="header-anchor" href="#運行遊戲" aria-label="Permalink to “運行遊戲”">​</a></h3><p><img src="https://linuxconfig.org/images/wow-api.jpg" alt="WoW Advanced Settings"></p><p>在 Battle.net 應用中點擊 “Play” 按鈕就能啓動 WoW 了。你需要等一會兒才能出現登錄界面， 這個性能簡直堪稱垃圾。 之所以這麼慢是因為 WoW 默認使用 DX11 來加速。 進入設置窗口中的 “Advanced” 標籤頁， 設置圖像 API 為 DX9。 保存然後退出遊戲。 退出成功後再重新打開遊戲。</p><p>現在遊戲應該可以玩了。請注意，遊戲的性能嚴重依賴於你的硬件水平。 WoW 是一個很消耗 CPU 的遊戲， 而 Wine 更加加劇了 CPU 的負擔。 如果你的 CPU 不夠強勁， 你的體驗會很差。 不過 WoW 支持低特效，因此你可以調低畫質讓遊戲更流暢。</p><h4 id="性能調優" tabindex="-1">性能調優 <a class="header-anchor" href="#性能調優" aria-label="Permalink to “性能調優”">​</a></h4><p><img src="https://linuxconfig.org/images/wow-settings.jpg" alt="WoW Graphics Settings"></p><p>很難説什麼樣的設置最適合你。WoW 在基本設置中有一個很簡單的滑動比例條。 它的配置應該要比在 Windows 上低幾個等級，畢竟這裏的性能不像 Windows 上那麼好。</p><p>先調低最可能的罪魁禍首。像<ruby>抗鋸齒<rt>anti-aliasing</rt></ruby>和<ruby>粒子<rt>particles</rt></ruby>就常常會導致低性能。 另外，試試對比一下窗口模式和全屏模式。 有時候這兩者之間的差距還是蠻大的。</p><p>WoW 對 “Raid and Battleground” 有專門的配置項。這可以在 “Raid and Battleground” 實例中的內容創建更精細的畫面。 有時間 WoW 在開放地圖中表現不錯， 但當很多玩家出現在屏幕中時就變得很垃圾了。</p><p>實驗然後看看哪些配置最適合你的系統。這完全取決於你的硬件和你的系統配置。</p><h3 id="最後結語" tabindex="-1">最後結語 <a class="header-anchor" href="#最後結語" aria-label="Permalink to “最後結語”">​</a></h3><p>雖然從未發佈過 Linux 版的魔獸世界，但它在 Wine 上已經運行很多年了。 事實上， 它幾乎一直都工作的很好。 甚至有傳言説暴雪的開發人員會在 Wine 上測試以保證它是有效的。</p><p>雖然有這個説法，但後續的更新和補丁還是會影響到這個古老的遊戲， 所以請隨時做好出問題的準備。 不管怎樣， 就算出問題了，也總是早已有了解決方案， 你只需要找到它而已。</p><hr>',17)),i("p",null,[n[13]||(n[13]=t("via: ",-1)),o(e,{href:"https://linuxconfig.org/how-to-play-world-of-warcraft-on-linux-with-wine"},{default:a(()=>[...n[12]||(n[12]=[t("https://linuxconfig.org/how-to-play-world-of-warcraft-on-linux-with-wine",-1)])]),_:1})]),i("p",null,[n[17]||(n[17]=t("作者：",-1)),o(e,{href:"https://linuxconfig.org"},{default:a(()=>[...n[14]||(n[14]=[t("Nick Congleton",-1)])]),_:1}),n[18]||(n[18]=t(" 譯者：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...n[15]||(n[15]=[t("lujun9972",-1)])]),_:1}),n[19]||(n[19]=t(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...n[16]||(n[16]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[22]||(n[22]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...n[20]||(n[20]=[t("LCTT",-1)])]),_:1}),n[23]||(n[23]=t(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:a(()=>[...n[21]||(n[21]=[t("Linux中國",-1)])]),_:1}),n[24]||(n[24]=t(" 榮譽推出",-1))])])}const L=r(g,[["render",u]]);export{b as __pageData,L as default};
